// -------------------- CUSTOM FIELDS --------------------
function cfMap(customFields = {}) {
  const out = {};

  for (const [key, val] of Object.entries(customFields)) {
    if (!val) continue;

    const extracted =
      val.string ??
      val.integer ??
      val.boolean ??
      val.float ??
      val.date ??
      null;

    out[key] = extracted;
  }

  return out;
}

// -------------------- DESCRIPTION PARSING --------------------
function extractFirstLastSeen(description = "") {
  const firstMatch = description.match(/First seen\s*:\s*([^\n]+)/i);
  const lastMatch  = description.match(/Last seen\s*:\s*([^\n]+)/i);

  return {
    first_seen: firstMatch ? firstMatch[1].trim() : null,
    last_seen: lastMatch ? lastMatch[1].trim() : null
  };
}

// -------------------- NORMALIZERS --------------------
function normalizeBool(v) {
  if (v === true || v === false) return v;
  if (v == null) return null;
  const s = String(v).trim().toLowerCase();
  if (["true", "yes", "1"].includes(s)) return true;
  if (["false", "no", "0"].includes(s)) return false;
  return null;
}

function normalizeHostname(v) {
  if (!v || typeof v !== "string") return null;
  return v.trim().toLowerCase();
}

function normalizeIP(v) {
  if (!v || typeof v !== "string") return null;
  return v.trim();
}

// -------------------- ARTIFACT EXTRACTION --------------------
function extractArtifactsSmart(artifacts = []) {
  const out = {
    src_ip: null,
    dst_ip: null,
    domain: null,
    urls: [],
    user_agent: null,
    process_names: [],
    command_lines: [],
    file_paths: [],
    hashes: [],
    ports: [],
    raw: []
  };

  for (const a of artifacts) {
    if (!a?.data || !a?.dataType) continue;

    const v = String(a.data).trim();
    const t = a.dataType;

    out.raw.push({ type: t, value: v });

    if (t === "ip") {
      if (!out.src_ip) out.src_ip = v;
      else if (!out.dst_ip) out.dst_ip = v;
      continue;
    }

    if (t === "domain") {
      out.domain = v;
      continue;
    }

    if (t === "url") {
      out.urls.push(v);
      continue;
    }

    if (t === "user-agent") {
      out.user_agent = v;
      continue;
    }

    if (t === "hash") {
      out.hashes.push(v);
      continue;
    }

    if (t === "other") {
      const lower = v.toLowerCase();

      if (lower.endsWith(".exe")) {
        out.process_names.push(v);
      }

      if (v.includes(" ") && (v.includes(".exe") || v.includes("-"))) {
        out.command_lines.push(v);
      }

      if (v.includes("\\") || v.includes("/")) {
        out.file_paths.push(v);
      }

      if (/^\d{2,5}$/.test(v)) {
        out.ports.push(v);
      }
    }
  }

  return out;
}

// -------------------- CLASSIFICATION --------------------
function classifyAlert(a) {
  const title = (a.title || "").toLowerCase();
  const source = (a.source || "").toLowerCase();
  const role = `${a.src_role || ""} ${a.dst_role || ""}`.toLowerCase();

  if (
    title.includes("powershell") ||
    title.includes("encodedcommand") ||
    title.includes("iex")
  ) {
    return {
      alert_type: "powershell_execution",
      playbook: "windows_powershell_investigation",
      default_time_window_minutes: 5,
      elastic_targets: ["endpoint_process", "powershell", "winlogbeat"],
      event_focus: ["process", "network", "dns"],
      max_events: 20
    };
  }

  if (
    title.includes("file") ||
    title.includes("process") ||
    title.includes("webshell")
  ) {
    if (role.includes("iis") || role.includes("web server")) {
      return {
        alert_type: "web_file_or_process_activity",
        playbook: "iis_webshell_or_process_investigation",
        default_time_window_minutes: 10,
        elastic_targets: ["endpoint_process", "endpoint_file", "iis"],
        event_focus: ["process", "file", "network"],
        max_events: 20
      };
    }

    return {
      alert_type: "windows_file_or_process_activity",
      playbook: "windows_file_process_investigation",
      default_time_window_minutes: 5,
      elastic_targets: ["endpoint_process", "endpoint_file"],
      event_focus: ["process", "file"],
      max_events: 20
    };
  }

  if (
    title.includes("scan") ||
    title.includes("nmap") ||
    source.includes("opnsense")
  ) {
    return {
      alert_type: "network_scan_or_recon",
      playbook: "network_scan_investigation",
      default_time_window_minutes: 3,
      elastic_targets: ["suricata", "firewall"],
      event_focus: ["network"],
      max_events: 30
    };
  }

  if (
    title.includes("web") ||
    title.includes("http")
  ) {
    return {
      alert_type: "web_activity",
      playbook: "iis_web_investigation",
      default_time_window_minutes: 10,
      elastic_targets: ["iis"],
      event_focus: ["web", "network"],
      max_events: 20
    };
  }

  return {
    alert_type: "generic_security_alert",
    playbook: "generic_investigation",
    default_time_window_minutes: 5,
    elastic_targets: ["endpoint_process", "suricata"],
    event_focus: ["process", "network"],
    max_events: 15
  };
}

// -------------------- OSINT TARGETS --------------------
function buildOsintTargets(a) {
  const targets = [];

  if (a.src_ip) targets.push({ type: "ip", value: a.src_ip });
  if (a.dst_ip) targets.push({ type: "ip", value: a.dst_ip });

  if (a.domain) targets.push({ type: "domain", value: a.domain });

  for (const u of a.urls || []) {
    targets.push({ type: "url", value: u });
  }

  for (const h of a.hashes || []) {
    targets.push({ type: "hash", value: h });
  }

  for (const c of a.command_lines || []) {
    if (
      c.toLowerCase().includes("http") ||
      c.toLowerCase().includes("powershell")
    ) {
      targets.push({ type: "command_line", value: c });
    }
  }

  return targets;
}

// -------------------- SUMMARY --------------------
function buildSummary(a) {
  return [
    `${a.alert_type} from ${a.source}`,
    a.src_ip && a.dst_ip ? `${a.src_ip} → ${a.dst_ip}` : null,
    a.process_names?.length ? `proc: ${a.process_names.slice(0,2).join(",")}` : null,
    a.urls?.length ? `url: ${a.urls[0]}` : null,
    a.hashes?.length ? `hash: ${a.hashes[0].slice(0,12)}...` : null,
    `priority=${a.soc_priority ?? "n/a"}`
  ].filter(Boolean).join(" | ");
}

// -------------------- MAIN --------------------
return items.map(item => {
  const j = item.json;

  const cf = cfMap(j.customFields || {});
  const seen = extractFirstLastSeen(j.description || "");
  const artifacts = extractArtifactsSmart(j.artifacts || []);

  const cleaned = {
    alert_id: j._id || null,
    title: j.title || null,
    source: cf.detection_source || j.source || null,
    severity: j.severity ?? null,
    date: j.date || null,

    alert_count: cf.alert_count ?? null,
    asset_flow: cf.asset_flow || null,

    src_ip: normalizeIP(cf.src_ip || artifacts.src_ip),
    dst_ip: normalizeIP(cf.dst_ip || artifacts.dst_ip),

    src_asset: normalizeHostname(cf.primary_asset || null),
    src_role: cf.primary_role || null,
    src_os: cf.primary_os || null,

    soc_priority: cf.soc_priority ?? null,

    domain: artifacts.domain,
    urls: artifacts.urls,
    user_agent: artifacts.user_agent,

    process_names: artifacts.process_names,
    command_lines: artifacts.command_lines,
    file_paths: artifacts.file_paths,
    hashes: artifacts.hashes,
    ports: artifacts.ports,

    first_seen: seen.first_seen,
    last_seen: seen.last_seen
  };

  const classification = classifyAlert(cleaned);

  Object.assign(cleaned, classification);

  cleaned.osint_targets = buildOsintTargets(cleaned);

  cleaned.summary_for_ai = buildSummary(cleaned);

  return { json: cleaned };
});

const output = [];

for (const item of items) {
  const alert = item.json;

  const rawTargets = alert.osint_targets || [];

  // --- helper: check private/internal IPs ---
  const isPrivateIP = (ip) => {
    if (!ip) return true;

    return (
      ip.startsWith('10.') ||
      ip.startsWith('192.168.') ||
      ip.startsWith('172.16.') ||
      ip.startsWith('172.17.') ||
      ip.startsWith('172.18.') ||
      ip.startsWith('172.19.') ||
      ip.startsWith('172.2') // covers 172.20–172.29
    );
  };

  // --- helper: validate OSINT target ---
  const isValidTarget = (t) => {
    if (!t || !t.value) return false;

    switch (t.type) {
      case 'ip':
        return !isPrivateIP(t.value);

      case 'domain':
        return !t.value.includes('windowsupdate.com');

      case 'url':
        return t.value.length > 5;

      case 'hash':
        return t.value.length >= 32;

      case 'command_line':
        return false;

      default:
        return false;
    }
  };

  // --- filter targets ---
  const filteredTargets = rawTargets.filter(isValidTarget);

  const hasOsint = filteredTargets.length > 0;

  // 🔴 IMPORTANT CHANGE: emit ONE ITEM PER TARGET
  if (hasOsint) {
    for (const t of filteredTargets) {
      output.push({
        json: {
          // 🔹 target (used by Dispatcher)
          type: t.type,
          value: t.value,

          // 🔹 keep alert context
          alert_id: alert.alert_id,
          title: alert.title,
          source: alert.source,
          severity: alert.severity,
          soc_priority: alert.soc_priority,

          // 🔹 keep original fields if needed downstream
          ...alert,

          // 🔹 control flags (still preserved)
          has_osint_targets: true,
          enrichment_status: "pending",
          osint_target_count: filteredTargets.length
        }
      });
    }
  } else {
    // 🔹 preserve alerts with NO OSINT targets (important for your IF node)
    output.push({
      json: {
        ...alert,
        osint_targets_filtered: [],
        has_osint_targets: false,
        enrichment_status: "skipped",
        osint_target_count: 0
      }
    });
  }
}

return output;

// === OSINT Summarizer (Compact, No Bloat, No Drops) ===

return items.map(item => {
  const data = item.json;

  // -----------------------------
  // Normalize alert
  // -----------------------------
  const alert = (data.alert && Object.keys(data.alert).length > 1)
    ? data.alert
    : data;

  const lookup = data.lookup_result || data.lookup_results || {};
  const type = data.type || "unknown";
  const value = data.value || null;

  const hasLookup = Object.keys(lookup).length > 0;

  // -----------------------------
  // Helpers
  // -----------------------------
  const safe = (v, def = null) =>
    v === undefined || v === null ? def : v;

  // -----------------------------
  // 🔥 TRIM LOOKUP (CRITICAL)
  // -----------------------------
  function trimLookup() {
    const trimmed = {};

    if (lookup.shodan) {
      trimmed.shodan = {
        isp: lookup.shodan.isp,
        org: lookup.shodan.org,
        ports: (lookup.shodan.ports || []).slice(0, 10)
      };
    }

    if (lookup.abuseipdb) {
      trimmed.abuseipdb = {
        score: lookup.abuseipdb.score,
        country: lookup.abuseipdb.country,
        usage_type: lookup.abuseipdb.usage_type
      };
    }

    if (lookup.virustotal?.raw?.data?.attributes) {
      const attr = lookup.virustotal.raw.data.attributes;

      trimmed.virustotal = {
        reputation: attr.reputation,
        malicious: safe(attr.last_analysis_stats?.malicious, 0),
        suspicious: safe(attr.last_analysis_stats?.suspicious, 0),
        tags: (attr.tags || []).slice(0, 5),
        last_analysis: attr.last_analysis_date
      };
    }

    return trimmed;
  }

  // -----------------------------
  // IP Summary
  // -----------------------------
  function summarizeIP() {
    const shodan = lookup.shodan || {};
    const abuse = lookup.abuseipdb || {};

    let classification = "unknown";

    if ((shodan.isp || "").toLowerCase().includes("cloudflare")) {
      classification = "trusted_cdn";
    } else if ((abuse.score || 0) > 50) {
      classification = "likely_malicious";
    } else if ((abuse.score || 0) > 0) {
      classification = "suspicious";
    }

    return {
      indicator: value,
      type: "ip",
      classification,
      abuse_score: safe(abuse.score, 0),
      isp: safe(shodan.isp),
      country: safe(abuse.country),
      confidence: hasLookup ? 1 : 0
    };
  }

  // -----------------------------
  // Domain Summary
  // -----------------------------
  function summarizeDomain() {
    const vt = lookup.virustotal || {};
    const attr = vt?.raw?.data?.attributes || {};

    const malicious = safe(attr.last_analysis_stats?.malicious, 0);

    let classification = "unknown";

    if (malicious > 5) classification = "malicious";
    else if (malicious > 0) classification = "suspicious";

    return {
      indicator: value,
      type: "domain",
      classification,
      malicious,
      reputation: safe(attr.reputation, 0),
      confidence: vt?.raw?.data ? 1 : 0
    };
  }

  // -----------------------------
  // Hash Summary
  // -----------------------------
  function summarizeHash() {
    const vt = lookup.virustotal || {};
    const attr = vt?.raw?.data?.attributes || {};

    const malicious = safe(attr.last_analysis_stats?.malicious, 0);

    let classification = "clean";
    if (malicious > 10) classification = "malicious";
    else if (malicious > 0) classification = "suspicious";

    return {
      indicator: value,
      type: "hash",
      classification,
      malicious,
      file_type: attr.type_description,
      confidence: vt?.raw?.data ? 1 : 0
    };
  }

  // -----------------------------
  // URL Summary (for Nmap alerts)
  // -----------------------------
  function summarizeURL() {
    const u = (value || "").toLowerCase();

    let classification = "unknown";

    if (u.includes("hnap") || u.includes("sdk")) {
      classification = "scan_probe";
    } else if (u.includes("login") || u.includes("admin")) {
      classification = "sensitive_endpoint";
    }

    return {
      indicator: value,
      type: "url",
      classification,
      confidence: 0.5
    };
  }

  // -----------------------------
  // Dispatcher
  // -----------------------------
  let osint_summary;

  if (!hasLookup) {
    osint_summary = {
      indicator: value,
      type,
      classification: "no_enrichment",
      confidence: 0
    };
  } else if (type === "ip") {
    osint_summary = summarizeIP();
  } else if (type === "domain") {
    osint_summary = summarizeDomain();
  } else if (type === "hash") {
    osint_summary = summarizeHash();
  } else if (type === "url") {
    osint_summary = summarizeURL();
  } else {
    osint_summary = {
      indicator: value,
      type,
      classification: "unsupported",
      confidence: 0
    };
  }

  // -----------------------------
  // FINAL OUTPUT (CLEAN)
  // -----------------------------
  return {
    json: {
      alert_id: alert.alert_id,
      alert,
      type,
      value,

      osint_summary,
      enrichment_confidence: osint_summary.confidence,

      // 🔥 trimmed instead of full raw dump
      lookup_summary: trimLookup()
    }
  };
});

return items.map(item => {
  const report = item.json.output || item.json;
  const alertTitle = item.json.alert?.title || "Security Alert";
  const severity = item.json.alert?.severity || "Unknown";

  // Choose an emoji based on severity
  const icon = severity >= 4 ? "🔴" : "🟠";

  const message = `
### ${icon} SOC Alert Handoff: ${alertTitle}
---
${report}

---
*Report generated by Qwen2.5:7b • [Open TheHive](http://172.16.218.12:9000)*
  `.trim();

  return {
    json: {
      text: message,
      username: "Qwen-SOC-Agent",
      icon_url: "https://n8n.io" // Or any robot icon URL
    }
  };
});

return items.map(item => {
  const i = item.json;

  const verdict = i.final_verdict;
  const alert = i.alert || {};
  const score = i.risk_score || 0;

  let decision = {
    action: null,
    priority: null,
    playbook: null,
    reason: null
  };

  // =========================
  // HIGH RISK → FULL RESPONSE
  // =========================
  if (verdict === "HIGH") {
    decision.action = "create_case";

    // Prioritize stronger attacks
    if (score >= 90) {
      decision.priority = "P1";
    } else {
      decision.priority = "P2";
    }

    // Map playbooks
    if (alert.alert_type === "powershell_execution") {
      decision.playbook = "EDR_Containment";
    } 
    else if (alert.alert_type === "web_activity") {
      decision.playbook = "Web_Server_Compromise";
    } 
    else {
      decision.playbook = "Generic_Threat_Investigation";
    }

    decision.reason = "High risk behavior + correlation detected";
  }

  // =========================
  // MEDIUM → INVESTIGATE
  // =========================
  else if (verdict === "MEDIUM") {
    decision.action = "create_alert";

    decision.priority = "P3";
    decision.playbook = "Threat_Hunting";

    decision.reason = "Suspicious behavior requires investigation";
  }

  // =========================
  // LOW → SUPPRESS / LOG
  // =========================
  else {
    if (alert.alert_type === "benign_update_activity") {
      decision.action = "auto_close";
      decision.reason = "Known benign update traffic";
    } else {
      decision.action = "log_only";
      decision.reason = "Low risk signal";
    }

    decision.priority = "P5";
    decision.playbook = "None";
  }

  // Attach decision
  i.decision = decision;

  return { json: i };
});

// === CONFIG ===
const TRUSTED_DOMAINS = [
  "windowsupdate.com",
  "microsoft.com",
  "azureedge.net"
];

// === HELPERS ===
function isTrustedDomain(domain) {
  if (!domain) return false;
  return TRUSTED_DOMAINS.some(d => domain.includes(d));
}

function isWindowsUpdate(alert) {
  return (
    alert.user_agent?.includes("Microsoft-Delivery-Optimization") ||
    alert.urls?.some(u => u.includes("msdownload")) ||
    isTrustedDomain(alert.domain)
  );
}

function buildFullUrls(alert) {
  if (!alert.urls) return [];
  if (!alert.domain) return alert.urls;

  return alert.urls.map(u => {
    if (u.startsWith("http")) return u;
    return `http://${alert.domain}${u}`;
  });
}

// === GROUPING ===
function getGroupingKey(item) {
  const alert = item.alert || {};

  // 1. Use domain if present (Windows Update etc.)
  if (alert.domain) {
    return `domain:${alert.domain}`;
  }

  // 2. Use type:value for IP / hash / domain alerts
  if (item.type && item.value) {
    return `${item.type}:${item.value}`;
  }

  // 3. Fallback: use alert_id so every generic alert is its own group
  return `alert_id:${item.alert_id || item.alert?.alert_id || Math.random()}`;
}

// === SCORING ===
function scoreItem(item) {
  let score = 0;

  const alert = item.alert && Object.keys(item.alert).length > 1
  ? item.alert
  : item;
  const osint = item.osint_summary || {};

  const title = (alert.title || "").toLowerCase();
  const flow = (alert.asset_flow || "").toLowerCase();
  const role = (alert.src_role || "").toLowerCase();

  const hasOSINT = item.has_osint_targets;

  // =========================
  // 1. OSINT
  // =========================
  if (osint.detection?.malicious > 10) score += 30;
  else if (osint.detection?.malicious > 0) score += 15;

  if (osint.reputation?.abuse_score > 50) score += 15;

  // =========================
  // 2. BEHAVIOR (REDUCED + CONTROLLED)
  // =========================

  // Critical attacks
  if (title.includes("kerberoast") || flow.includes("credential access")) {
    score += 60;
  }

  // Persistence / Priv Esc
  else if (title.includes("admin account creation") || flow.includes("persistence")) {
    score += 50;
  }

  // Discovery
  else if (title.includes("discovery") || flow.includes("discovery")) {
    score += 30;
  }

  // =========================
  // 3. CONTEXT (NO DUPLICATION)
  // =========================
  if (role.includes("domain controller")) {
    score += 25;
  } else if (role.includes("server")) {
    score += 15;
  }

  // Severity
  if (alert.severity >= 5) score += 25;
  else if (alert.severity === 4) score += 15;

  // SOC priority (reduced weight)
  score += (alert.soc_priority || 1) * 5;

  // =========================
  // 4. NO OSINT (FLAT BONUS, NO MULTIPLIER)
  // =========================
  if (!hasOSINT) {
    score += 10;
  }

  // =========================
  // 5. SIGNALS
  // =========================
  if (alert.command_lines?.some(cmd =>
    cmd.toLowerCase().includes("executionpolicy bypass")
  )) score += 20;

  if (alert.process_names?.some(p =>
    p.toLowerCase().includes("printspoofer")
  )) score += 40;

  if (alert.process_names?.some(p =>
    p.toLowerCase().includes("sandcat")
  )) score += 35;

  if (alert.command_lines?.some(cmd =>
    cmd.includes(":8888")
  )) score += 25;

  // =========================
  // 6. CORRELATION
  // =========================
  if (item.occurrences > 2) score += 10;
  if (item.related_alerts?.length > 2) score += 10;

  // =========================
  // 7. BENIGN OVERRIDE (KEEP)
  // =========================
  if (isWindowsUpdate(alert)) {
    score = Math.min(score, 20);
  }

  return Math.max(0, Math.min(100, Math.round(score)));
}

function verdictFromScore(score) {
  if (score >= 70) return "HIGH";
  if (score >= 40) return "MEDIUM";
  return "LOW";
}

// === MAIN ===

// 1. Normalize
const normalized = items.map(item => {
  const i = item.json;

  i.alert = i.alert || {};
  i.osint_summary = i.osint_summary || {};

  i.alert.urls = buildFullUrls(i.alert);

  if (isWindowsUpdate(i.alert)) {
    i.alert.alert_type = "benign_update_activity";
    i.alert.playbook = "ignore_or_whitelist";
  }

  if (i.type === "ip" && isTrustedDomain(i.alert.domain)) {
    i.osint_summary.classification = "trusted_vendor";
  }

  return i;
});

// 2. Group
const grouped = {};

for (const item of normalized) {
  const key = getGroupingKey(item);

  if (!grouped[key]) {
    grouped[key] = {
      ...item,
      occurrences: 1,
      related_alerts: [item.alert.alert_id]
    };
  } else {
    grouped[key].occurrences++;
    grouped[key].related_alerts.push(item.alert.alert_id);
  }
}

// 3. Score
for (const key in grouped) {
  const item = grouped[key];

  const score = scoreItem(item);
  item.risk_score = score;
  item.final_verdict = verdictFromScore(score);
}

// 4. Noise suppression
// === NOISE SUPPRESSION (improved) ===
const NOISE_SUPPRESSION_THRESHOLD = 1;        // ← you can change this
const MIN_SOC_PRIORITY_TO_KEEP = 3;       // keep everything >=4 even if LOW

// === FINAL FILTER ===
const result = Object.values(grouped).filter(i => {
  const verdict = i.final_verdict;
  const occurrences = i.occurrences || 1;
  const socPriority = i.alert?.soc_priority || i.soc_priority || 4;

  // Keep HIGH and MEDIUM no matter what
  if (verdict === "HIGH" || verdict === "MEDIUM") {
    return true;
  }

  // NEVER drop high-priority alerts (Kerberoasting = 5, local admin = 4, etc.)
  if (socPriority >= MIN_SOC_PRIORITY_TO_KEEP) {
    return true;
  }

  // Only suppress true noise: LOW risk + very rare
  return !(verdict === "LOW" && occurrences <= NOISE_SUPPRESSION_THRESHOLD);
});

// 5. Output
return result.map(i => ({ json: i }));

const globalSet = new Set();
const results = [];

// ---- VALIDATORS ----

function isValidHash(h) {
  return /^[a-fA-F0-9]{32}$|^[a-fA-F0-9]{40}$|^[a-fA-F0-9]{64}$/.test(h);
}

function isValidIP(ip) {
  if (!ip) return false;
  const parts = ip.split('.');
  return parts.length === 4 && parts.every(p => {
    const n = Number(p);
    return n >= 0 && n <= 255;
  });
}

function isLikelyDomain(d) {
  if (!d) return false;

  const lower = d.toLowerCase();

  // ❌ Reject filenames / code artifacts
  if (
    lower.endsWith('.exe') ||
    lower.endsWith('.dll') ||
    lower.endsWith('.ps1') ||
    lower.endsWith('.bat') ||
    lower.endsWith('.go') ||
    lower.includes('system.') ||
    lower.includes('wc.') ||
    lower.includes('headers')
  ) return false;

  // Must have at least one dot
  if (!d.includes('.')) return false;

  // Basic domain pattern
  return /^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(d);
}

function extractIPs(text) {
  if (!text) return [];
  return text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [];
}

function extractDomains(text) {
  if (!text) return [];
  return text.match(/\b[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}\b/g) || [];
}

